scenarios.example_code:
import { configureRegion } from '@projexlight/sdk-sovereign';
await configureRegion({
  name: 'de-sovereign',
  regulatory_profile: ['BDSG','GDPR','C5'],
  allowed_providers: ['azure-eu-de','aws-eu-central-1','aleph-alpha'],
  attestation_key_id,
});

import { releaseBundle } from '@projexlight/sdk-sovereign';
const { release_id } = await releaseBundle({
  region: 'fedramp-us-east',
  bundle_id: 'projexcloud-v3.2',
  attestation_chain: [...], // SLSA-3 provenance
});

import { verifyAttestation } from '@projexlight/sdk-sovereign';
const { ok, reason } = await verifyAttestation({
  bundle_id: process.env.BUNDLE_ID,
});
if (!ok) { process.exit(1); }

import { startLeakMonitor } from '@projexlight/sdk-sovereign';
startLeakMonitor({
  region_pair: ['eu-de','us-east'], halt_pipeline_on_detection: true,
});

subscribeEvents('vault.key.rotated.v1', async (e) => {
  await reVerifyAttestationsForKey({ old_key_id: e.payload.from_key_id });
});
